printf '%s\n' 'import argparse' 'import json' 'import sys' '' 'parser = argparse.ArgumentParser()' 'parser.add_argument("config")' 'parser.add_argument("--env", choices=["dev", "staging", "prod"], default="dev")' 'args = parser.parse_args()' 'cfg = json.load(open(args.config))' 'if "app" not in cfg or "defaults" not in cfg:' '    sys.exit("error: missing key")' 'merged = {**cfg["defaults"], **cfg.get("environments", {}).get(args.env, {})}' 'print(json.dumps(merged, sort_keys=True))' > build_config.py
